<script setup lang="ts">
import { ref } from 'vue';
const props = defineProps<{
    color:string
}>()
const color = ref(props.color);
const hover = ref(false);
const isActive = ref(false); // 新增一个状态来跟踪是否点击激活

const changecolor = () => {
    isActive.value = !isActive.value; // 切换isActive状态
    // 如果点击后激活，且当前颜色不是#f9f221（即原始颜色），则更改为#f9f221
    // 否则，改回原始颜色#218ef9
    if (isActive.value && color.value !== '#f92125') {
        color.value = '#f92125';
    } else if (!isActive.value && color.value === '#f92125') {
        color.value = props.color;
    }
    // 注意：这里我们不需要在悬浮时改变color的值，因为hover已经通过:fill属性直接处理了
};
</script>